INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Кӯбок яке аз муҳимтарин қаттиҳҳои ба сабукидани ду-сола мебошад, ки ба сабаби афзоиши тез ва арзиши ошёрнаваи баланд дар миёни деҳқоноён диққат мекушояд. Аммо яке аз мушкилоти асосӣ дар сабукидани ин намуд, паҳншавии зараррасонҳо ва бемориҳои растаниҳо мебошад, ки метавонад таъсири мустақим ба сифат ва миқдори маҳсулот расонад. Дар усулҳои анъанавии обёрӣ, ба монанди обёрии пухта, зиёдшавии намнокӣ дар болои хок ва ҳавои дар атрофи растани, заминаи муносибро барои рушди қолабҳо ва мӯрҳои хокӣ фароҳам меорад. Аз ҷониби дигар, <strong>Зараррасонҳо ва бемориҳои кӯбок бо обёрии қатрагӣ</strong> идоракунии бешубора муассиртар доранд, зеро ин системаҳо бо фароҳам овардани шартҳои оҳанги намнокӣ барои реша ва хушк нигоҳ доштани қисмҳои ҳавоии растани, зanjирро аз интиқоли унсурҳои бемориивиро мебуранд. Ин роҳбарӣ на танҳо аз нигоҳи бехатсии растаниҳо, балки аз нигоҳи самаранокии истифодаи манбаъҳои обӣ низ аҳамияти калон дорад. Дар ин навиштаҷот, тафсилоти техникӣ ва амалии идоракунии патосфераи кӯбок бо истифода аз технологияҳои нав обёрии маҳаллӣ муҳолла намуда мешаванд, то деҳқонон бо огоҳии пурра аз паҳншавии зараррасии бадбарор пешгирӣ карда тавонанд.</p><h2>Таъсири обёрии қатрагӣ ба патосфераи кӯбок</h2><p>Қисми ихтисосӣ дар поён таъсироти физиологикӣи обёрии қатрагӣ ба паҳншавии бемориҳоро муҳолла мекунад. Дар кӯбок, бемориҳои фангусӣ ба монанди антракноз, дараки барг ва хӯроки реша аз зиёдтарин унсурҳои зараррасанда мебошанд. Ин бемориҳо барои ҷаворидан ба оҳанги намнокии баланди болои баргҳо ва хунӯк будани доимиҳои спорҳои қолабӣ ниёз доранд. Системаҳои нӯбартипӣ бо обёрии мустақим ба минтақаи реша ва намнок накардани баргҳо, ин шартҳоро нест мекунанд. Ҳамчунин, камшавии ҷараёни ҳавои намнок байни тӯкҳои дар системаи қатрагӣ, ба ҳавои мухаллифи хокистон мусоидат мекунад, ки рафторидани спорҳои қолабиро кам мекунад. Ин механизм барои пешгирӣ аз доираи дуюми заҳршавӣ дар фаслҳои намнок ҳаётӣ аст. Воқеан, нигоҳ доштани мувозинати намнокӣ дар болои хок бе эҷоди пухтаи, аз фаъолияти энзимҳои зараррасанда дар ҳуҷайраҳои растаниҳо пешгирӣ мекунад ва устувии ҳаводоро кафолат мекунад. Бинобар ин, интихоби андозаи мувофиқи қатраҳо ва суръати обёрӣ, бевосита ба сатҳи фишори қолабӣ-ҳамкорӣ ва дар натиҷа ба миқдори зарари расида ба маҳсулоти ниҳоӣ таъсир мекунад.</p><figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-باقلا-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های باقلا با آبیاری قطره‌ای - تصویر 1"/><figcaption>zararрасонҳои бемориҳои ҳосил обёрии қатрагӣ кӯбок</figcaption></figure><h3>Пешгирӣ аз бемориҳои реша бо идоракунии нӯбартипӣ</h3><p>Бемориҳои решаи кӯбок аксаран бо спорҳои фусарий ё агроботикҳои питуо майкосом (Phytophthora) шадид мешаванд. Зичшавии нӯбартипӣ бо масофати мувофиқ, аз ҷамъи зиёди намнокӣ дар чуқурии хок пешгирӣ мекунад. Деҳқон бояд масофат байни нӯбҳоро тавре тартиб диҳад, ки ҳар нӯб минтақаи решаи худро ба таври якхела намнок кунад, бе онки минтақаи маҳдудшуда бо намнокӣ бе намнокӣ бигардонад. Ин кор ба дониши дақиқ аз чуқурии решагирии кӯбок ниёз дорад, ки дар фасли афзоиш одатан то чуқурии 60 то 80 сантиметр паҳн мешавад. Идоракунии дақиқи намнокии хок дар ин чуқурӣ, калиди мубориза бо зараррасониҳои хокӣ аст. Агар решаҳо доимо дар робита бо намнокии суст бошанд, оксиданизи биологӣ қатъ мешавад ва решаҳо дар муҳарраби патогенҳои беҳавоӣ менависанд. Барои пешгирӣ аз вазъияти чунин, истифодаи сенсориҳои ҷеҳоннамо барои танзими динамикаи намнокӣ дар решагузорӣ зарур аст. Ин танзимот бояд бар асоси намуди хок ва ҳарорати муҳитиazor, пеш аз оғоз тартиб дода шуда бошанд, то аз ҳар гуна стресси обгардонӣ ё хушкшавии ногаҳонӣ пешгирӣ карда шавад.</p><ul><li>Истифодаи нӯбҳои ду-монанд барои пӯшиши беҳтар минтақаи реша.</li><li>Танзими фишори система барои пешгирӣ аз даридани реша бо сабаби ҷамъшавии об дар атрофи нӯб.</li><li>Мунтазам сохтани ҳисоботҳо ба тавре, ки болои хоки нӯб хушк монда шавад.</li><li>Назорати ҳафтаномаи чуқурии намнокии хок бо истифода аз сенсорҳои намнокӣ барои ислоҳи меъёри об.</li></ul><h2>Идоракунии зараррасониҳои ҳашаротӣ дар муҳити обёрии қатрагӣ</h2><p>Гарчанде ки оборириш ноқтарӣ ба таври мустақим ҳамчун усули назорати кимиёвӣ барои ҳашарот амал намекунад, вале тавассути тағйироти экологии, ки ба вуҷуд меояд, рафтори мисҳоро зид мекунад. Баъзе мисҳои хӯрандаи парҳа, ба монанди заргарӣ ва нисҳӯр, дар шароити рагузи баланд ба таври шадид паҳн мешаванд. Дар ҳолати хушк нигоҳ доштани сатҳи баргҳо бо системаи ноқтарӣ, муҳассир шудани мисҳои хӯрандаи парҳаро душвор менамояд. Инчунин, имконияти якҷоя кардани системаи обориш бо моддаҳои қумқузазакуз ва назоратгарони биологӣ дар системаҳои пешрафтаи ноқтарӣ, дастрасии мустақим ба омилҳои назораткунандаро имконпазир мекунад. Дар ин соҳа, таҳқиқот дар бораи <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A8%D8%A7%D9%82%D9%84%D8%A7-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Микдори бобиби баргилок дар гектар</a> метавонад ба кишоварз кӯмак расонад, то зичии мувофиқеро барои назорати афрӯидашавии мисҳо асосан дар асоси фазои сабз интихоб кунад. Зичии мувофиқи номи, фосилакунии барои ҷараёни ҳаворо зиёд мекунад. Бо зиёдшавии фазои сабз, гардиши ҳаво байни номиҳо осон шуда ва рагузи нисбӣ дар қатлҳои поёнӣ кам мешавад. Ин боис мешавад, ки спорҳо ва либӯни ҳашарот фурсати камтар барои ҷойгир шудан ва нисҳароӣ дошта бошанд. Илова бар ин, рӯши офтоб низ бо гузашни озод аз байни номиҳои зич, ба фурӯ рӯйдан баъзе омилҳои мунҳандиёнд, ки ба рагузи сайоғайнӯз ниёз доранд, кӯмак мекунад. Бинобар ин, идоракунии зичии калонкунии дар паҳлӯи системаи обориш, як стратегияи дӯгуниро барои назорати биологӣи зарароварон ташкил медиҳад, ки хароҷоти кимиёвиеро ба таври қобили дидашавӣ кам мекунад.</p><figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-باقلا-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های باقلا با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation баргилок</figcaption></figure><h3>Нуқтаҳои амалиягӣ барои кам кардани зарари зарароварон</h3><p>Барои он ки аз тамоми имконияти оборириш ноқтарӣ дар идоракунии мисҳо истифода баред, нуқтаҳои зеринро дар назар доред:</p><ol><li><strong>Назорати карбҳо:</strong> Дар системаи ноқтарӣ, сатҳи хок аз карбҳо (қуттиҳои калонкунии) озод аст, ки ҷои пинҳон шудани мисҳои хӯрандаи парҳа мебошанд. Ин хусусият, ниёз ба зарбаҳои кимиёвиҳои мустақимро ба баргҳо кам мекунад.</li><li><strong>Оборириш аз боло дар моҳи охирин:</strong> Дар марҳилаҳои охирини рушди баргилок, вақте ки ном дар ҳолати дарахтшавӣ аст, кам шудани тадриҷии оборириш ва зиёд шудани фосилаҳои оборириш, монеи паҳн шудани заргарӣ дар навъҳо мешавад.</li><li><strong>Истифода аз наварҳои ҳаракатпазир:</strong> Истифодаи <a href="https://navar-abyari.ir/%D8%B4%D8%B1%D9%8A%D8%B7-%D8%A7%D9%84%D8%B1%D9%8A-%D8%A8%D8%A7%D9%84%D8%AA%D9%86%D9%82%D9%8A%D8%B7-%D9%81%D9%8A-%D8%A8%D8%B5%D8%B1%D9%87/">навари оборириш дар баргилок</a> ё наварҳои полиетиленӣ бо намудиҳисоби муборакӣ, кӯмак мекунад, то ки мисҳои хӯрандаи парҳа наметавонанд тавассути сӯроҳҳои навар ба сатҳи рӯйхатҳои хомӯшкундагон расанд.</li><li><strong>Ҳамзамони зарфашуудани решаӣ:</strong> Истифода аз системаҳои фертигация барои инъикор ба моддаҳои ғизоии махсус, ки муборакати номро дар назди стрессҳои ҳашаротӣ баланд мебаранд, тавсия дода мешавад.</li></ol><h2>Ҷадвали муқоисавӣ: Оборириш ноқтарӣ дар муқобилаи гарғубият барои назорати беморӣ</h2><table border="1" style="width:100%; border-collapse: collapse; border: 1px solid #ccc;">\n<tr><th style="padding: 8px; text-align: left; background-color: #f2f2f2;">Параметр</th><th style="padding: 8px; text-align: left; background-color: #f2f2f2;">Орошение методом затопления</th><th style="padding: 8px; text-align: left; background-color: #f2f2f2;">Капельное орошение / линейное орошение (тип)</th></tr>\n<tr><td style="padding: 8px; text-align: left;">Влажность поверхности листьев</td><td style="padding: 8px; text-align: left;">Очень высокая (благоприятная среда для развития грибов)</td><td style="padding: 8px; text-align: left;">Низкая (предотвращение развития грибов)</td></tr>\n<tr><td style="padding: 8px; text-align: left;">Аэрация почвы</td><td style="padding: 8px; text-align: left;">Слабая (застой воды)</td><td style="padding: 8px; text-align: left;">Хорошая (точечное управление влажностью)</td></tr>\n<tr><td style="padding: 8px; text-align: left;">Доставка контролируемых веществ</td><td style="padding: 8px; text-align: left;">Невозможно или неэффективно</td><td style="padding: 8px; text-align: left;">Возможно (внесение под корень)</td></tr>\n<tr><td style="padding: 8px; text-align: left;">Урон от тли (комары-наездники или подобные вредители)</td><td style="padding: 8px; text-align: left;">Выше (высокая влажность)</td><td style="padding: 8px; text-align: left;">Ниже (относительная сухость)</td></tr>\n</table><p>Как показано в таблице, система линейного орошения (тип) имеет абсолютное превосходство не только с точки зрения потребления воды, но и с точки зрения фитосанитарного состояния. Это преимущество особенно критично во влажных регионах, где распространение ржавчины нута возрастает. Для более глубокого понимания взаимосвязи между управлением линейным орошением и продуктивностью, изучение текста «Шарит аль-ри» в «Касиде» может дать более глубокое понимание принципов проектирования ирригационных линий при различных почвенных и климатических условиях. Эта информация помогает выбрать более подходящую модель оборудования при покупке. Кроме того, с учетом коэффициента надежности для климатических колебаний при проектировании системы, фермер сможет обеспечить необходимую влажность даже в жаркие и сухие дни, не мокая листья растения, что предотвратит развитие пятнистых заболеваний.</p><figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-باقلا-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های باقلا با آبیاری قطره‌ای - تصویر 3"/><figcaption>вредители болезней капельное орошение нут</figcaption></figure><h2>Итоги и окончательные рекомендации</h2><p>Управление вредителями и болезнями нута с помощью капельного орошения — это комплексный подход, который требует тщательности при проектировании системы. Среди окончательных рекомендаций можно выделить следующие: во-первых, регулируйте интервалы между линиями орошения в соответствии с глубиной корней нута, чтобы предотвратить пересыхание или затопление корней. Во-вторых, используйте высококачественные линии с подходящими суспензиями; для получения технической информации об этих линиях, см. страницу <a href="https://navar-abyari.ir/samak-jidar-sharit-al-ray/">Намаки шити риштавии оборӣ</a> омӯзед. Се-йум, агар ҳоҷияти идоракунии кимиёвӣ вуҷуд дошта бошад, аз омехтаи ободорӣ бо пашашҳои решагӣ (Fertigation) истифода баред, то моддаҳои фаъол бевосита ба минтақаи решаҳо расанд. Бо иҷрои дурусти ин нуқтаҳо, метавон умедворӣ дошт, на танҳо ҳаҷми зарари занбӯрунҳо кам мешавад, балки самаранокии ниҳоии маҳсулот низ беҳтар мешавад. Истифода аз <a href="https://navar-abyari.ir/%D8%A7%D9%86%D9%88%D8%A7%D8%B9-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE/">навъҳои риштаҳои оборӣ</a> мувофиқ ба вазъиятҳои толор, қадами дигар дар самти беҳтар кардани тамоми толори нахӯд ҳисоб мешавад. Дар охир, назорати доимии ҳолати растани дар ҷанбаи системаи оборӣ, ягона роҳ барои пешгирии паҳншавии ногаҳонии муҳарриқҳо мебошад. Ин усулҳо ба деҳқон имкон медиҳанд, ки бо хароҷоти камтар ва сифати баландтар, маҳсулоти солимро ба бозор расонанд. Сармоягузорӣ дар технологияҳои дақиқи оборӣ, дар давоми муҳлати дароз мусоид ба кам шудани партовҳо ва зиёд шудани фоидаи толори нахӯд хоҳад буд.</p>','Идоракунии зараррасон ва бемориҳои бешук дар системаи обёркунӣ бо тамға: Раҳнамои умумӣ','Ормон бағалӣ ва ҷоғалӣ нақши калидиро дар идоракунии бемориҳои занбӯри ғулоб боз мекунад. Дар ин мақола, мо раҳҳои амалӣ барои камак кардани сироятҳо ва зиёд кардани ҳосили ғулоб бо нигоҳ ба идоракунии намӣ омӯзед.','publish','closed','closed','idarokunii-zararroson-o-bemorihoi-beshuk',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
